class BondMode(OpenEnum):
    """A bonding mode specifies the policy indicating how bonding slaves are used during
    network transmission. - BOND_MODE_UNSPECIFIED: BOND_MODE_UNSPECIFIED : if bonding mode
    is not explicitly specified, then by default Round-Robin policy is applied
    (BOND_MODE_BALANCE_RR). - BOND_MODE_BALANCE_RR: BOND_MODE_BALANCE_RR : transmit packets
    in sequential order from the first available slave through the last. This mode provides
    load balancing and fault tolerance. This is the default bonding mode. -
    BOND_MODE_ACTIVE_BACKUP: BOND_MODE_ACTIVE_BACKUP : only one slave in the bond is active.
    A different slave becomes active if, and only if, the active slave fails. The bond's MAC
    address is externally visible on only one port to avoid confusing the switch. This mode
    provides fault tolerance. - BOND_MODE_BALANCE_XOR: BOND_MODE_BALANCE_XOR : packet source
    and destination MAC addresses are used to calculate hash and select the output slave
    interface accordingly. This algorithm will place all traffic destined to a particular
    network peer on the same slave. This mode provides load balancing and fault tolerance. -
    BOND_MODE_BROADCAST: BOND_MODE_BROADCAST: transmits everything on all slave interfaces.
    This mode provides fault tolerance. - BOND_MODE_802_3AD: BOND_MODE_802_3AD : IEEE
    802.3ad Dynamic link aggregation. Creates aggregation groups that share the same speed
    and duplex settings. Utilizes all slaves in the active aggregator according to the
    802.3ad specification. Requires that upstream networks equipment supports and has the
    IEEE 802.3ad Dynamic link aggregation properly configured. - BOND_MODE_BALANCE_TLB:
    BOND_MODE_BALANCE_TLB : adaptive transmit load balancing. Channel bonding that does not
    require any special switch support. The outgoing traffic is distributed according to the
    current load (computed relative to the speed) on each slave. Incoming traffic is
    received by the current slave. If the receiving slave fails, another slave takes over
    the MAC address of the failed receiving slave. This mode provides (TX) load balancing
    and fault tolerance. - BOND_MODE_BALANCE_ALB: BOND_MODE_BALANCE_ALB : adaptive load
    balancing. Includes BOND_MODE_BALANCE_TLB plus receive load balancing (RLB) for IPV4
    traffic, and does not require any special switch support. The receive load balancing is
    achieved by ARP negotiation. This mode provides load balancing and fault tolerance
    """

    BOND_MODE_UNSPECIFIED = "BOND_MODE_UNSPECIFIED"
    BOND_MODE_BALANCE_RR = "BOND_MODE_BALANCE_RR"
    BOND_MODE_ACTIVE_BACKUP = "BOND_MODE_ACTIVE_BACKUP"
    BOND_MODE_BALANCE_XOR = "BOND_MODE_BALANCE_XOR"
    BOND_MODE_BROADCAST = "BOND_MODE_BROADCAST"
    BOND_MODE_802_3AD = "BOND_MODE_802_3AD"
    BOND_MODE_BALANCE_TLB = "BOND_MODE_BALANCE_TLB"
    BOND_MODE_BALANCE_ALB = "BOND_MODE_BALANCE_ALB"


