class ConfigCellularConnectivityProbe(ZedcloudModel):
    """CellularConnectivityProbe is used to periodically check the connectivity status of a
    cellular network by probing a remote endpoint. Whenever the probe fails, the cellular
    connection is automatically restarted. If the probe keeps failing even after the
    restart, the failure is reported in ZCellularStatus.probeError. The connectivity probing
    interval is 5 minutes and currently it is not configurable
    """

    disable: bool | None = Field(default=None, description="If true, then probing is disabled")
    probe_address: str | None = Field(
        default=None,
        alias="probeAddress",
        description="IP/FQDN to periodically probe using 3 pings per iteration to determine connectivity status. This field is now deprecated and replaced with custom_probe (see below). To maintain backward-compatibility, EVE will check both probe_address and custom_probe and will use whichever has non-zero value (if any), but preferring custom_probe",
    )
    custom_probe: CommonConnectivityProbe | None = Field(
        default=None,
        alias="customProbe",
        description='User-defined probe for cellular connectivity testing. Only IP address is allowed as ConnectivityProbe.probe_address (and port if needed), not hostname. The probing algorithm is more complex that just testing reachability of a remote endpoint and the goal is to minimize generated traffic, probing time and false negatives (that would trigger undesired re-connect). EVE will periodically check the modem status, accessibility of DNS server(s) and potentially also proxies in the local network, and only as the last resort (if connectivity state is still unclear) it will probe the remote endpoint. If custom_probe is not defined, EVE will try to ping "8.8.8.8" (Google public DNS). It is recommended to use custom probe for private LTE networks where public DNS servers might not be allowed by the firewall (and hence ping would fail even with a working connectivity)',
    )


