class ConfigPhysicalIO(ZedcloudModel):
    """PhysicalIO: Absolute low level description of physical buses and ports that are
    available on given platform. Collection of these IOs, constitute what we would call as
    hardware model. Each physical IO is manageable and visible to EVE software, and it can
    be further configured to either provide IP connectivity or directly be given to
    workloads
    """

    ptype: CommonPhyIoType | None = Field(default=None)
    phylabel: str | None = Field(
        default=None,
        description="physical label typically printed on box. Example Eth0, Eth1, Wifi0, ComA, ComB",
    )
    phyaddrs: _t.Dict[str, str] | None = Field(
        default=None,
        description='The hardware bus address. The key to this map can be of the following (case-insensitive) values: "pcilong": the address is a PCI id of the form 0000:02:00.0 "ifname": the address is a string for a network interface like "eth1" "serial": the address is a Linux serial port alias such as "/dev/ttyS2" "irq": the address is a number such as "5". This can be a comma separated list of integers or even a range of integers. Hence using a string to address this. "ioports": the address is a string such as "2f8-2ff" "usbaddr": the address is a USB of the form of "1:2.3" If the type is PhyIoNet*, then there needs to be an "ifname" physaddr',
    )
    logicallabel: str | None = Field(
        default=None,
        description="logicallabel - provides the ability to model designer to refer the physicalIO port to using more friendly name For example Eth0->Mgmt0 or USBA->ConfigDiskA etc",
    )
    assigngrp: str | None = Field(
        default=None,
        description="assigngrp Assignment Group, is unique label that is applied across PhysicalIOs EntireGroup can be assigned to application or nothing at all — This is the name used in AppInstanceConfig.adapters to assign an adapter to an application. If assigngrp is not set, the Adapter cannot be assigned to any application. One example is, when the adapter is on the same Pci bus as another device required by Dom0. Even if there is only one device on the its PCIBus, the assignGrp Must be set",
    )
    usage: CommonPhyIoMemberUsage | None = Field(
        default=None,
        description="usage - indicates the role of adapter ( mgmt / blocked / app-direct etc. )",
    )
    usage_policy: ConfigPhyIOUsagePolicy | None = Field(
        default=None,
        alias="usagePolicy",
        description="usagePolicy - Policy Object used to further refine the usage. For example, specify if this should be only used as fallback? Or used as the primary uplink? Allow App traffic? restrict app traffic?? etc",
    )
    cbattr: _t.Dict[str, str] | None = Field(
        default=None,
        description="physical and logical attributes For example in WWAN to which firmware version to load etc",
    )
    vflist: ConfigVfList | None = Field(
        default=None,
        description="list of Virtual Functions (VF) for given Physical Function (PF) only applies for PHY_IO_TYPE_PHY_IO_NET_ETH_PF",
    )
    parentassigngrp: str | None = Field(
        default=None,
        description="parentassigngrp — Parent Assignment Group is there to reference the parent assignment group in order to make the device dependent on a different device. Currently the concrete reason to do this is to make a usb device dependent on the PCI address the USB controller is using to prevent passthrough of the USB controller in one application while trying to passthrough a USB device on this controller to another application. We only allow these two cases: - children and their parent devices are assigned to the same application instance - parent device stays in host and one or more children (in separate assignment groups) are assigned to one or more application instances",
    )


