class ConfigSystemAdapter(ZedcloudModel):
    """systemAdapters are higher-level IP-ready network endpoints. systemAdapters give all the
    required bits to turn the physical IOs and intermediate L2 objects into useful IP
    endpoints. These endpoints can be further used to connect to controller or can be shared
    between workload/services running on the node
    """

    name: str | None = Field(
        default=None,
        description="name - Name of the Network Interface. This is the Port Name used in Info / Metrics / flowlog etc. Name cannot be changed. This will be the Network Port name",
    )
    free_uplink: bool | None = Field(
        default=None, alias="freeUplink", description="DEPRECATED by cost below"
    )
    uplink: bool | None = Field(
        default=None,
        description="uplink - DEPRECATED by PhysicalIO.Usage / PhysicalIO.UsagePolicy this is part of the uplink group deprecate: have a separate device policy object in the API",
    )
    network_uuid: str | None = Field(
        default=None,
        alias="networkUUID",
        description="networkUUID - attach this network config for this adapter if not set, depending on Usage of Adapter, would be treated as an L2 port",
    )
    addr: str | None = Field(
        default=None,
        description="addr - if its static network we need ip address If this is specified, networkUUID must also be specified. addr is expected to be in sync with the network object (same subnet etc )",
    )
    alias: str | None = Field(
        default=None,
        description="alias - Device just reflects it back in status / Metrics back to cloud",
    )
    lower_layer_name: str | None = Field(
        default=None,
        alias="lowerLayerName",
        description="lowerLayerName - For example, if lower layer is PhysicalAdapter ( physical interface), this should point to logicallabel of the physicalIO",
    )
    cost: int | None = Field(
        default=None,
        description="Cost of sending traffic over the port. Used to prioritize ports and give preference to lower-cost ports (e.g. eth over wwan). 0 is the lowest cost (free); 255 the highest. Can be set for management and app-shared ports. Cost is used for EVE management traffic and for local network instances with multiple ports. For any request towards the controller or for an image download, EVE tries ports in the order of increasing cost, starting with the free ports. Once it finds the lowest cost port with a working connectivity, it may spread the load if there are multiple connected ports of the same cost. For local networking instances with multiple ports, the cost may be used to decide which port to use for a particular destination network (incl. port selection for the default route). Unlike the management traffic, load-balancing is currently not supported for local network instances and the app traffic that is routed through them",
    )
    shared_labels: _t.List[str] | None = Field(
        default=None,
        alias="sharedLabels",
        description='A set of user-defined "shared" labels attached to the adapter. There are no restrictions on the format of an adapter label, it can be any non-empty string. Unlike the logical label (aka port logical name), shared label is not a unique port identifier. Instead, the same shared label can be assigned to multiple ports. Note that EVE automatically assigns "all" label to every port, "uplink" label to every management port and "freeuplink" label to every management port with zero cost. ("automatically assigns" is meant here in imaginary sense, these labels are not supposed to be explicitly added by the controller to SystemAdapters inside EdgeDevConfig). Shared label can be used to: - designate a group of network adapters to be used by a network instances for external connectivity - limit port-forwarding firewall rule to only a subset of network adapters - create a multi-path static IP route (with multiple ports providing access to the routed destination network)',
    )
    allow_local_modifications: bool | None = Field(
        default=None,
        alias="allowLocalModifications",
        description="Allow the local operator to make (limited) configuration changes to this network adapter",
    )


