class EnrolledCertStatus(OpenEnum):
    """Certificate lifecycle and availability status as reported by the device. -
    ENROLLED_CERT_STATUS_AVAILABLE: Certificate is present, valid, and usable for
    authentication. - ENROLLED_CERT_STATUS_PENDING: Certificate enrollment is in progress
    and not yet complete. - ENROLLED_CERT_STATUS_RENEWAL_PENDING: Certificate is present and
    still valid, but a renewal request is in progress and not yet completed. -
    ENROLLED_CERT_STATUS_EXPIRED: Certificate has expired (the current time is past
    notAfter). Renewal may have failed; see err for related errors. -
    ENROLLED_CERT_STATUS_REVOKED: Certificate has been revoked or is otherwise considered
    invalid. - ENROLLED_CERT_STATUS_ENROLLMENT_FAILED: Certificate enrollment failed and no
    valid certificate is available. - ENROLLED_CERT_STATUS_RENEWAL_FAILED: A certificate is
    currently present but the most recent renewal attempt failed. -
    ENROLLED_CERT_STATUS_INVALID_CONFIG: Certificate configuration is invalid or malformed,
    preventing enrollment or renewal
    """

    ENROLLED_CERT_STATUS_UNSPECIFIED = "ENROLLED_CERT_STATUS_UNSPECIFIED"
    ENROLLED_CERT_STATUS_AVAILABLE = "ENROLLED_CERT_STATUS_AVAILABLE"
    ENROLLED_CERT_STATUS_PENDING = "ENROLLED_CERT_STATUS_PENDING"
    ENROLLED_CERT_STATUS_RENEWAL_PENDING = "ENROLLED_CERT_STATUS_RENEWAL_PENDING"
    ENROLLED_CERT_STATUS_EXPIRED = "ENROLLED_CERT_STATUS_EXPIRED"
    ENROLLED_CERT_STATUS_REVOKED = "ENROLLED_CERT_STATUS_REVOKED"
    ENROLLED_CERT_STATUS_ENROLLMENT_FAILED = "ENROLLED_CERT_STATUS_ENROLLMENT_FAILED"
    ENROLLED_CERT_STATUS_RENEWAL_FAILED = "ENROLLED_CERT_STATUS_RENEWAL_FAILED"
    ENROLLED_CERT_STATUS_INVALID_CONFIG = "ENROLLED_CERT_STATUS_INVALID_CONFIG"


