class SWState(OpenEnum):
    """State of EVE/Edge Application software — - SW_STATE_RESOLVING_TAG: Prior to
    DOWNLOAD_STARTED we go through these: Resolving an image tag - SW_STATE_RESOLVED_TAG:
    Tag has been resolved/failed - SW_STATE_CREATING_VOLUME: Prior to INSTALLED we go
    through these: Volume create in progress - SW_STATE_CREATED_VOLUME: Volume create
    done/failed - SW_STATE_VERIFYING: Verification in-progress - SW_STATE_LOADING: Loading
    blob in CAS - SW_STATE_LOADED: Loaded blob in CAS - SW_STATE_AWAITNETWORKINSTANCE: Wait
    for network instance
    """

    SW_STATE_UNSPECIFIED = "SW_STATE_UNSPECIFIED"
    SW_STATE_INITIAL = "SW_STATE_INITIAL"
    SW_STATE_DOWNLOAD_IN_PROGRESS = "SW_STATE_DOWNLOAD_IN_PROGRESS"
    SW_STATE_DOWNLOADED = "SW_STATE_DOWNLOADED"
    SW_STATE_VERIFIED = "SW_STATE_VERIFIED"
    SW_STATE_INSTALLED = "SW_STATE_INSTALLED"
    SW_STATE_BOOTING = "SW_STATE_BOOTING"
    SW_STATE_RUNNING = "SW_STATE_RUNNING"
    SW_STATE_HALTING = "SW_STATE_HALTING"
    SW_STATE_HALTED = "SW_STATE_HALTED"
    SW_STATE_REFRESHING = "SW_STATE_REFRESHING"
    SW_STATE_PURGING = "SW_STATE_PURGING"
    SW_STATE_RESOLVING_TAG = "SW_STATE_RESOLVING_TAG"
    SW_STATE_RESOLVED_TAG = "SW_STATE_RESOLVED_TAG"
    SW_STATE_CREATING_VOLUME = "SW_STATE_CREATING_VOLUME"
    SW_STATE_CREATED_VOLUME = "SW_STATE_CREATED_VOLUME"
    SW_STATE_VERIFYING = "SW_STATE_VERIFYING"
    SW_STATE_LOADING = "SW_STATE_LOADING"
    SW_STATE_LOADED = "SW_STATE_LOADED"
    SW_STATE_AWAITNETWORKINSTANCE = "SW_STATE_AWAITNETWORKINSTANCE"


